import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.QQy01QNh.js";const p=JSON.parse('{"title":"A.11　HV11 开放性承担行动（完整接口卡）","description":"","frontmatter":{"title":"A.11　HV11 开放性承担行动（完整接口卡）"},"headers":[],"relativePath":"theory/appendix-a/a-11.md","filePath":"theory/appendix-a/a-11.md"}'),i={name:"theory/appendix-a/a-11.md"};function o(n,t,l,b,_,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<div class="theory-source"><h1 id="section-a-11" tabindex="-1">A.11　HV11 开放性承担行动（完整接口卡） <a class="header-anchor" href="#section-a-11" aria-label="Permalink to &quot;A.11　HV11 开放性承担行动（完整接口卡） {#section-a-11}&quot;">​</a></h1><p>A. 身份、命题与适用范围</p><table tabindex="0"><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>接口 ID（id）</td><td>HV11</td></tr><tr><td>限定 ID（qualified_id）</td><td>human_variable:HV11</td></tr><tr><td>名称（name）</td><td>开放性承担行动</td></tr><tr><td>主张类型（claim_type）</td><td>H</td></tr><tr><td>合同角色（contract_role）</td><td>human_variable_interface</td></tr><tr><td>命题（proposition）</td><td>开放性承担只观察真实成本、自愿性、方向、替代解释和结构后果，不诊断某人有没有爱。</td></tr><tr><td>适用范围（scope）</td><td>人类关系、组织、制度与公共行动中的承担</td></tr><tr><td>暂停条件（pause_condition）</td><td>无法安全确认自愿、拒绝或退出时，暂停R1开放性承担命名；仍可按R0登记候选行动、成本、强制风险、停止权缺口与保护需求。人格与爱的诊断始终禁止。</td></tr></tbody></table><p>B. 正式依赖与结论边界</p><table tabindex="0"><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>推理依赖（inferential_requires）</td><td>无（空集合）</td></tr><tr><td>协议依赖（protocol_requires）</td><td>1. N4<br>2. EVIDENCE<br>3. SOURCE</td></tr><tr><td>限定／特化（specializes）</td><td>1. H6<br>2. H2</td></tr><tr><td>适用对象引用（applies_to）</td><td>无（空集合）</td></tr><tr><td>条件支持路由（conditional_support_routes）</td><td>1. route_id=HV11-R0-action-cost-record；<br>claim_level=normative_boundary；<br>when=行动与相关成本有据，可记录方向、受益及后果的已知或未知状态，但自愿性、拒绝或退出尚不充分。；<br>additional_inferential_requires=无（空集合）；<br>additional_protocol_requires=无（空集合）；<br>allowed_conclusion=描述候选承担行动、成本分布、强制风险、停止权缺口与保护需求。；<br>result_ceiling=不得称开放性承担，不得诊断爱、人格或要求继续承担。<br>2. route_id=HV11-R1-voluntary-limited-action；<br>claim_level=normative_boundary；<br>when=行动及真实成本有据，方向明确，自愿性、真实拒绝、退出或协商条件分别得到支持，并检查相关替代解释；结果按实现、未实现、有害或未知记录，不以结构成功为准入。；<br>additional_inferential_requires=无（空集合）；<br>additional_protocol_requires=无（空集合）；<br>allowed_conclusion=登记有限自愿承担描述及结果状态；失败或结果未知不取消有据的行动与自愿性事实。；<br>result_ceiling=只到行动描述；不把个体承担升格为群体义务，也不授权征用、保护或资源安排。<br>3. route_id=HV11-R2-structural-consequence；<br>claim_level=conditional_effect；<br>when=符合资格的G2-instance显示该行动经指定通道对预选结构结果产生超过阈值的效应。；<br>additional_inferential_requires=G2-instance；<br>additional_protocol_requires=CAUSAL、E4；<br>allowed_conclusion=登记指定通道、对象与窗口内的行动结构后果。；<br>result_ceiling=结构效应不证明自愿性、爱、善、正当性、无限责任或行动授权；R2对效应的支持不能替R1补证，受强制行动也可能有可识别效应。</td></tr><tr><td>允许推论（allowed_inference）</td><td>1. 描述有限承担行动与后果</td></tr><tr><td>禁止跳跃（prohibited_leap）</td><td>1. 诊断有没有爱<br>2. 牺牲等于爱<br>3. 责任等于无限承担<br>4. 拒绝等于道德失败</td></tr></tbody></table><p>C. 九轴尺度与对象合同</p><table tabindex="0"><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>九轴尺度画像（scale_profile）</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;；A=聚合层次：单次承担行动、行动者个案、关系或组织总体、成本自愿性分布及聚合规则；X=空间范围：关系与照护现场、组织边界、数字公共空间与跨域受益范围；T=时间跨度：即时行动、持续承担、耗竭、恢复与代际窗口；O=组织层级：行动角色、关系或团队、组织、制度至治理生态；C=因果层次：承担事件、行动—成本互动机制、中观关系结构、制度责任安排与系统条件；R=观察分辨率：原始行动与成本、承担序列、行动者个案、成本自愿性分布、后果指标与摘要，并登记压缩损失；I=影响范围：直接行动者与受益者、依赖者、间接替代承接者、二阶外溢、跨域与代际影响；N=网络拓扑范围：依赖照护、受益连接、替代承接、退出路径与跨域成本网络；J=管辖与授权范围：承担要求、资源使用、拒绝、停止、保护与补救分别登记授权；保留自愿成本退出差异</td></tr><tr><td>有效对象（effective_object）</td><td>需要分别审查行动、成本、方向、自愿性、拒绝条件和后果的人类承担安排；R0、R1、R2按各自条件判断，不先用结构后果筛选行动</td></tr><tr><td>跨尺度保持项（scale_invariants）</td><td>1. 成本、自愿性、方向、替代解释、后果与停止权</td></tr><tr><td>升格必补项（required_scale_additions）</td><td>1. 自愿性分布<br>2. 代表关系<br>3. 成本外溢<br>4. 真实退出与代理保护</td></tr><tr><td>随尺度改变项（changing_semantics）</td><td>1. 承担形式、成本位置和受益对象可改变</td></tr><tr><td>不适用对象（non_applicable_objects）</td><td>1. 无意向、自愿性、责任或意义能力的非人系统</td></tr><tr><td>禁止升格（forbidden_elevation）</td><td>1. 个体承担升格为群体义务<br>2. 人类承担概念迁入非人核心</td></tr></tbody></table><p>D. 状态、证据与变量流</p><table tabindex="0"><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>状态集合（state）</td><td>1. 候选<br>2. 自愿且有限<br>3. 强制风险<br>4. 单方耗竭<br>5. 停止或退出</td></tr><tr><td>可观测项（observables）</td><td>1. 行动投入的时间、资源、机会与身体心理成本<br>2. 拒绝、退出、停止和重新协商是否真实可用<br>3. 行动方向、受益位置和可检测结构后果<br>4. 强制、恐惧、依赖、利益与表演等替代解释</td></tr><tr><td>证据要求（evidence）</td><td>1. 行动与成本<br>2. 拒绝和退出条件<br>3. 替代解释<br>4. 受益与后果</td></tr><tr><td>输入依赖与接口内容（input_dependencies）</td><td>1. 指向锚点<br>2. 承接层<br>3. 条件势场<br>4. 权力与安全</td></tr><tr><td>输出效应与变量流（output_effects）</td><td>1. 成本分布<br>2. 关系和制度状态<br>3. 停止与修复</td></tr><tr><td>时间窗与时滞（time_window_and_lag）</td><td>登记即时成本、持续承担、耗竭与恢复时滞</td></tr><tr><td>不确定性（uncertainty）</td><td>记录依赖、恐惧、隐性强制与表达安全</td></tr><tr><td>局部排除区（local_exclusion_zone）</td><td>无法安全拒绝、无法退出或被道德压力遮蔽的位置</td></tr><tr><td>受影响位置（affected_positions）</td><td>1. 行动者<br>2. 受益者<br>3. 依赖者<br>4. 替代承接者</td></tr></tbody></table><p>E. 承接、责任、规范、上限与纠错</p><table tabindex="0"><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>承接载体（carrier）</td><td>1. 具体行动者<br>2. 关系实践<br>3. 照护或责任安排</td></tr><tr><td>责任主体（responsible_subject）</td><td>1. 提出要求者<br>2. 授权者<br>3. 受益责任者<br>4. 补救责任者</td></tr><tr><td>规范地位（normative_status）</td><td>受N4约束，不可命令或征用</td></tr><tr><td>判断上限（judgment_ceiling）</td><td>按R0/R1/R2分别限制：R0只作成本、方向、风险及候选行动描述；R1在相应证据下作自愿性、拒绝和退出条件的行动描述；R2只有在相应G2及因果条件成立时，才作限定范围的结构后果判断。任何一级均不得进入人格诊断、证明爱或善、推出承担义务或生成现实授权。伦理命名另受GOV-14的规范前提约束，不能以达到R2代替该要求。</td></tr><tr><td>行动上限（action_ceiling）</td><td>本变量只生成自愿性、真实成本、方向、替代解释、结构后果与停止保护需求描述，不授权保护措施、承担要求、资源征用或人格裁决；任何现实调整须另过C12、运行时显式N前提、J授权与O程序</td></tr><tr><td>反例（counterexamples）</td><td>1. 无法拒绝的单方牺牲被赞美为爱或责任<br>2. 承担宣称缺少所称行动或成本的证据；真实失败尝试与结果未知另记，不能因无结构成功而一概撤销其行动描述</td></tr><tr><td>申诉（appeal）</td><td>依appeal_and_rollback_rule，行动者可经安全可达、反报复通道拒绝被代表，说明强制、成本、替代解释和退出限制，并触发与原承担判断或要求链独立的复核</td></tr><tr><td>回滚（rollback）</td><td>依appeal_and_rollback_rule，获准回滚时，由指定责任人在规定时限内撤销承担命名与相关要求，实际恢复拒绝、退出、记录和资源状态，保留版本与完成验证</td></tr></tbody></table><p>scale_profile 不是“微观—宏观”的单轴标签，而是 SP=&lt;A,X,T,O,C,R,I,N,J&gt; 的完整九轴记录：A 是聚合层次，必须声明单元、总体、分布和聚合规则；X 是物理空间与数字边界；T 是窗口、时滞和周期；O 是角色、团队、组织、制度与治理生态的组织层级；C 是事件、互动机制、中观结构、制度和系统条件的因果层次；R 是原始事件、序列、个案、分布、指标与摘要的观察分辨率，并记录压缩损失；I 是直接、间接、二阶、跨域与代际的受影响范围；N 是网络拓扑范围；J 是管辖与授权范围。扩大 A、X、O 或 I 不会自动扩大 J；观察更多不能产生更大处置权。</p><p>身份与同一性判据属于对象合同 K，关系与作用通道进入 input_dependencies、carrier 或因果合同，成员与受影响位置进入 affected_positions、local_exclusion_zone 和观察字段；它们都不能冒充尺度轴。尺度轴 N 指网络拓扑；下文“运行时显式 N 前提”指规范选择层 N1-N5，两者不可混用。</p><p>十一项变量共享同一行动边界：变量本身只生成描述、证据缺口与行动需求，不授权现实调整。其输出上限如下。</p><table tabindex="0"><thead><tr><th>变量</th><th>本变量可生成的描述或需求</th></tr></thead><tbody><tr><td>HV01</td><td>候选结构域、边界争议与补证需求</td></tr><tr><td>HV02</td><td>边界状态、接口障碍、排除风险与测试需求</td></tr><tr><td>HV03</td><td>候选锚点、异质表达、比较结果与补证需求</td></tr><tr><td>HV04</td><td>GC、GS、GE 候选分型、状态转移与补证需求</td></tr><tr><td>HV05</td><td>CV、RS、成本、容量、停止权、承接缺口及减载、补资源或重分配需求</td></tr><tr><td>HV06</td><td>链条连通、时滞、损耗、中断、成本与承接需求</td></tr><tr><td>HV07</td><td>受理、字段变化、执行、持续时间、写回缺口与程序修复需求</td></tr><tr><td>HV08</td><td>候选条件通道、位置异质性、证据遮蔽与风险降低需求</td></tr><tr><td>HV09</td><td>负荷、容量、恢复、局部过载与减载补资源需求</td></tr><tr><td>HV10</td><td>按所选路由的组件适用性、原型匹配与混合状态、限定相位机制或历史条件增量解释、独立X0路径状态、不确定性与观察需求</td></tr><tr><td>HV11</td><td>自愿性、真实成本、方向、替代解释、结构后果与停止保护需求</td></tr></tbody></table><p>无论需求看起来多么明显，任何现实调整都须另过 C12、运行时显式 N 前提、J 授权与 O 程序。变量不得自行授权测试、减载、补资源、修复、保护、归责、试探、推进、退出安排或处置。</p></div>',1)])])}const h=d(i,[["render",o]]);export{p as __pageData,h as default};
